DASHBOARD_HTML = r'''<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<title>VISION Command Center</title>
<style>
:root{--bg:#071016;--panel:#0d1a22;--panel2:#10242e;--line:#1c3a46;--text:#d9f3f2;--muted:#7fa6ad;--cyan:#5de7e1;--gold:#ffc857;--red:#ff6b6b;--green:#73e2a1}
*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 15% 0,#103642 0,#071016 38%,#050a0e 100%);color:var(--text);font:14px/1.5 system-ui,Segoe UI,sans-serif;min-height:100vh}
.shell{max-width:1440px;margin:auto;padding:24px}.top{display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);padding-bottom:20px}.brand{display:flex;gap:14px;align-items:center}.orb{width:48px;height:48px;border:2px solid var(--cyan);border-radius:50%;box-shadow:0 0 20px #5de7e155,inset 0 0 18px #5de7e133;display:grid;place-items:center;color:var(--cyan);font-weight:800}.eyebrow{color:var(--cyan);letter-spacing:.18em;text-transform:uppercase;font-size:11px}.title{font-size:28px;font-weight:700;letter-spacing:.04em}.status{color:var(--green);display:flex;gap:8px;align-items:center}.dot{width:9px;height:9px;background:var(--green);border-radius:50%;box-shadow:0 0 12px var(--green)}
.grid{display:grid;grid-template-columns:1.3fr .7fr;gap:18px;margin-top:18px}.panel{background:linear-gradient(145deg,#0e1e27dd,#09141bdd);border:1px solid var(--line);border-radius:14px;padding:18px;box-shadow:0 12px 40px #0003}.panel h2{margin:0 0 14px;font-size:15px;letter-spacing:.08em;text-transform:uppercase;color:var(--cyan)}.composer{display:flex;gap:10px}.composer textarea{flex:1;resize:vertical;min-height:72px;background:#071218;border:1px solid var(--line);border-radius:9px;color:var(--text);padding:12px;font:inherit}.button{border:1px solid var(--cyan);background:#0d343b;color:var(--cyan);border-radius:8px;padding:9px 14px;cursor:pointer;font-weight:700}.button:hover{background:#15515a}.button.warn{border-color:var(--gold);color:var(--gold);background:#382b0d}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:15px 0}.metric{background:#08151c;border:1px solid var(--line);padding:12px;border-radius:9px}.metric b{display:block;font-size:22px;color:var(--cyan)}.muted{color:var(--muted)}.agent{display:flex;justify-content:space-between;gap:12px;padding:11px 0;border-bottom:1px solid #16313a}.agent:last-child{border:0}.agent-name{font-weight:700}.tag{font-size:11px;color:var(--muted);border:1px solid var(--line);padding:2px 6px;border-radius:999px}.task{border:1px solid var(--line);border-radius:9px;padding:12px;margin:10px 0;background:#0a171e}.task-head{display:flex;justify-content:space-between;gap:10px}.pill{font-size:11px;border-radius:999px;padding:3px 8px;background:#16323a;color:var(--cyan)}.pill.completed{color:var(--green);background:#123a2a}.pill.awaiting_approval{color:var(--gold);background:#3c2d10}.pill.failed{color:var(--red);background:#421a20}.result{white-space:pre-wrap;color:#b9d7d5;margin-top:8px}.events{height:310px;overflow:auto;font:12px ui-monospace,Consolas,monospace}.event{padding:7px 0;border-bottom:1px solid #102730}.event b{color:var(--cyan)}.full{grid-column:1/-1}.empty{color:var(--muted);padding:20px 0;text-align:center}@media(max-width:900px){.grid{grid-template-columns:1fr}.full{grid-column:auto}.top{align-items:flex-start;gap:10px;flex-direction:column}}
</style></head>
<body><main class="shell"><header class="top"><div class="brand"><div class="orb">V</div><div><div class="eyebrow">Multi-agent command center</div><div class="title">VISION</div></div></div><div class="status"><span class="dot"></span><span id="status">connecting</span></div></header>
<section class="grid"><div class="panel"><h2>Command interface</h2><div class="composer"><textarea id="prompt" placeholder="Ask VISION to coordinate research, coding, diagnostics, or memory..."></textarea><button class="button" onclick="submitTask()">Dispatch</button></div><div class="metrics"><div class="metric"><span class="muted">Agents</span><b id="agent-count">—</b></div><div class="metric"><span class="muted">Tasks</span><b id="task-count">—</b></div><div class="metric"><span class="muted">Runtime</span><b id="provider">—</b></div></div><div id="tasks"></div></div>
<div class="panel"><h2>Agent network</h2><div id="agents"><div class="empty">Loading agent network…</div></div></div>
<div class="panel full"><h2>Live event stream</h2><div class="events" id="events"><div class="empty">Waiting for events…</div></div></div></section></main>
<script>
let lastEvent=0;
async function api(url,options){const r=await fetch(url,options);const d=await r.json();if(!r.ok)throw Error(d.error||'Request failed');return d}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
async function refresh(){try{const [health,agents,tasks,ev]=await Promise.all([api('/api/health'),api('/api/agents'),api('/api/tasks'),api('/api/events?after='+lastEvent)]);document.getElementById('status').textContent=health.status;document.getElementById('agent-count').textContent=health.agents;document.getElementById('task-count').textContent=tasks.tasks.length;document.getElementById('provider').textContent=health.llm_provider;document.getElementById('agents').innerHTML=agents.agents.map(a=>`<div class="agent"><div><div class="agent-name">${escapeHtml(a.name)}</div><div class="muted">${escapeHtml(a.description)}</div></div><span class="tag">${escapeHtml(a.risk_level)}</span></div>`).join('');document.getElementById('tasks').innerHTML=tasks.tasks.length?tasks.tasks.map(t=>`<div class="task"><div class="task-head"><b>${escapeHtml(t.prompt)}</b><span class="pill ${escapeHtml(t.status)}">${escapeHtml(t.status)}</span></div><div class="muted">${escapeHtml(t.route)} · ${escapeHtml(t.risk)} risk · ${escapeHtml(t.id.slice(0,8))}</div>${t.result?`<div class="result">${escapeHtml(t.result)}</div>`:''}${t.error?`<div class="result" style="color:var(--red)">${escapeHtml(t.error)}</div>`:''}${t.status==='awaiting_approval'?`<button class="button warn" onclick="approve('${t.id}')">Approve execution</button>`:''}</div>`).join(''):'<div class="empty">No tasks yet. Dispatch a command to activate the network.</div>';if(ev.events.length){lastEvent=ev.events[ev.events.length-1].sequence;const box=document.getElementById('events');if(box.querySelector('.empty'))box.innerHTML='';box.innerHTML=ev.events.map(e=>`<div class="event"><b>#${e.sequence} ${escapeHtml(e.kind)}</b> ${escapeHtml(e.message)} <span class="muted">${escapeHtml(new Date(e.created_at).toLocaleTimeString())}</span></div>`).join('')+box.innerHTML}}catch(e){document.getElementById('status').textContent='offline'}}
async function submitTask(){const input=document.getElementById('prompt');if(!input.value.trim())return;try{await api('/api/tasks',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({prompt:input.value})});input.value='';refresh()}catch(e){alert(e.message)}}
async function approve(id){await api('/api/tasks/'+id+'/approve',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});refresh()}
document.getElementById('prompt').addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')submitTask()});refresh();setInterval(refresh,1200);
</script></body></html>'''
